import React, {
  useEffect,
  useState,
} from "react";

import {
  Box,
  Button,
  FormControl,
  MenuItem,
  Select,
  SelectChangeEvent,
  Stack,
  Switch,
  Typography,
} from "@mui/material";

import {
  KeyboardArrowDownRounded,
  RefreshRounded,
} from "@mui/icons-material";

import {
  useForecastContext,
} from "../../contexts/ForecastContext";

import {
  useForecastEntities,
} from "../../features/forecast/hooks/useForecast";

import {
  ForecastEntity,
} from "../../features/forecast/types/forecast.types";

const ForecastContextBar = () => {
  const {
    horizon,
    metric,
    entityId,
    scenario,

    setHorizon,
    setMetric,
    setEntityId,
    setScenario,
  } = useForecastContext();

  /**
   * =====================================================
   * BACKEND ENTITIES
   * =====================================================
   */

  const {
    data,
    isLoading:
      entitiesLoading,
  } = useForecastEntities();

  /**
   * Explicitly tell TypeScript what the
   * backend entity data contains.
   */
  const forecastEntities: ForecastEntity[] =
    data ?? [];

  /**
   * =====================================================
   * LOCAL UI STATE
   * =====================================================
   */

  const [
    isScrolled,
    setIsScrolled,
  ] = useState(false);

  const [
    autoRefresh,
    setAutoRefresh,
  ] = useState(false);

  const [
    updatedAt,
    setUpdatedAt,
  ] = useState(
    new Date()
  );

  /**
   * =====================================================
   * SCROLL HANDLER
   * =====================================================
   *
   * When the user scrolls down, the large context
   * panel becomes a small fixed context bar.
   */

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(
        window.scrollY > 180
      );
    };

    window.addEventListener(
      "scroll",
      handleScroll,
      {
        passive: true,
      }
    );

    handleScroll();

    return () => {
      window.removeEventListener(
        "scroll",
        handleScroll
      );
    };
  }, []);

  /**
   * =====================================================
   * UPDATE TIME
   * =====================================================
   */

  useEffect(() => {
    setUpdatedAt(
      new Date()
    );
  }, [
    horizon,
    metric,
    entityId,
    scenario,
  ]);

  /**
   * =====================================================
   * AUTO REFRESH
   * =====================================================
   */

  useEffect(() => {
    if (!autoRefresh) {
      return;
    }

    const interval =
      window.setInterval(
        () => {
          setUpdatedAt(
            new Date()
          );
        },
        5 * 60 * 1000
      );

    return () => {
      window.clearInterval(
        interval
      );
    };
  }, [autoRefresh]);

  /**
   * =====================================================
   * KEEP ENTITY SELECTION VALID
   * =====================================================
   *
   * If the backend changes the available entities
   * and the currently selected entity no longer exists,
   * automatically select the first available entity.
   */

  useEffect(() => {
    if (
      forecastEntities.length === 0
    ) {
      return;
    }

    const entityExists =
      forecastEntities.some(
        (
          entity: ForecastEntity
        ) =>
          entity.id === entityId
      );

    if (!entityExists) {
      setEntityId(
        forecastEntities[0].id
      );
    }
  }, [
    forecastEntities,
    entityId,
    setEntityId,
  ]);

  /**
   * =====================================================
   * CHANGE HANDLERS
   * =====================================================
   */

  const handleHorizonChange = (
    event: SelectChangeEvent<string>
  ) => {
    setHorizon(
      event.target.value as typeof horizon
    );
  };

  const handleMetricChange = (
    event: SelectChangeEvent<string>
  ) => {
    setMetric(
      event.target.value as typeof metric
    );
  };

  const handleEntityChange = (
    event: SelectChangeEvent<string>
  ) => {
    setEntityId(
      event.target.value
    );
  };

  const handleScenarioChange = (
    event: SelectChangeEvent<string>
  ) => {
    setScenario(
      event.target.value as typeof scenario
    );
  };

  /**
   * =====================================================
   * RESET
   * =====================================================
   *
   * We don't use resetContext because that function
   * does not currently exist in ForecastContext.
   *
   * These are the dashboard defaults.
   */

  const handleReset = () => {
    setHorizon("daily");

    setMetric("burn");

    setScenario("actual");

    if (
      forecastEntities.length > 0
    ) {
      setEntityId(
        forecastEntities[0].id
      );
    }

    setUpdatedAt(
      new Date()
    );
  };

  /**
   * =====================================================
   * FORMATTED UPDATE TIME
   * =====================================================
   */

  const formattedUpdatedTime =
    updatedAt.toLocaleTimeString(
      [],
      {
        hour: "numeric",
        minute: "2-digit",
      }
    );

  /**
   * =====================================================
   * ENTITY OPTIONS
   * =====================================================
   */

  const renderEntityOptions = (
    compact = false
  ) => {
    if (entitiesLoading) {
      return (
        <MenuItem disabled>
          {compact
            ? "Loading..."
            : "Loading power stations..."}
        </MenuItem>
      );
    }

    if (
      forecastEntities.length ===
      0
    ) {
      return (
        <MenuItem disabled>
          No power stations available
        </MenuItem>
      );
    }

    return forecastEntities.map(
      (
        entity: ForecastEntity
      ) => (
        <MenuItem
          key={entity.id}
          value={entity.id}
        >
          {entity.label}
        </MenuItem>
      )
    );
  };

  /**
   * =====================================================
   * COMPACT STICKY VERSION
   * =====================================================
   */

  if (isScrolled) {
    return (
      <Box
        sx={{
          position: "fixed",

          top: 0,

          left: 0,

          right: 0,

          zIndex: 1200,

          bgcolor:
            "rgba(255,255,255,0.97)",

          backdropFilter:
            "blur(14px)",

          borderBottom:
            "1px solid #DCE3EE",

          boxShadow:
            "0 6px 20px rgba(23,43,77,0.08)",
        }}
      >
        <Box
          sx={{
            width: "100%",

            maxWidth: 1600,

            mx: "auto",

            px: {
              xs: 1.5,
              sm: 2,
              md: 3,
              lg: 4,
            },

            py: 1,
          }}
        >
          <Stack
            direction="row"
            alignItems="center"
            spacing={{
              xs: 1,
              md: 1.5,
            }}
            sx={{
              overflowX: "auto",

              "&::-webkit-scrollbar": {
                display: "none",
              },

              scrollbarWidth:
                "none",
            }}
          >
            {/* Context */}

            <Box
              sx={{
                display: {
                  xs: "none",
                  md: "block",
                },

                flexShrink: 0,
              }}
            >
              <Typography
                variant="caption"
                fontWeight={800}
                color="#68758A"
                sx={{
                  textTransform:
                    "uppercase",

                  letterSpacing:
                    "0.08em",
                }}
              >
                Context
              </Typography>
            </Box>

            {/* Horizon */}

            <CompactSelect
              value={horizon}
              onChange={
                handleHorizonChange
              }
              width={{
                xs: 150,
                md: 190,
              }}
            >
              <MenuItem value="daily">
                Tactical Daily
              </MenuItem>

              <MenuItem value="monthly">
                Strategic Monthly
              </MenuItem>
            </CompactSelect>

            {/* Metric */}

            <CompactSelect
              value={metric}
              onChange={
                handleMetricChange
              }
              width={{
                xs: 145,
                md: 180,
              }}
            >
              <MenuItem value="burn">
                Burn Predictions
              </MenuItem>

              <MenuItem value="supply">
                Supply Predictions
              </MenuItem>

              <MenuItem value="stockpile">
                Stockpile Predictions
              </MenuItem>
            </CompactSelect>

            {/* Entity */}

            <CompactSelect
              value={entityId}
              onChange={
                handleEntityChange
              }
              width={{
                xs: 125,
                md: 160,
              }}
            >
              {renderEntityOptions(
                true
              )}
            </CompactSelect>

            {/* Scenario */}

            <CompactSelect
              value={scenario}
              onChange={
                handleScenarioChange
              }
              width={{
                xs: 140,
                md: 180,
              }}
            >
              <MenuItem value="actual">
                Baseline
              </MenuItem>

              <MenuItem value="hotdry">
                Hot &amp; Dry
              </MenuItem>

              <MenuItem value="hotwet">
                Hot &amp; Wet
              </MenuItem>

              <MenuItem value="colddry">
                Cold &amp; Dry
              </MenuItem>

              <MenuItem value="coldwet">
                Cold &amp; Wet
              </MenuItem>
            </CompactSelect>

            <Box
              sx={{
                flex: 1,
                minWidth: 10,
              }}
            />

            {/* Updated */}

            <Typography
              variant="caption"
              color="#68758A"
              sx={{
                display: {
                  xs: "none",
                  lg: "block",
                },

                whiteSpace:
                  "nowrap",

                flexShrink: 0,
              }}
            >
              Updated{" "}
              {formattedUpdatedTime}
            </Typography>

            {/* Reset */}

            <Button
              variant="outlined"
              size="small"
              startIcon={
                <RefreshRounded />
              }
              onClick={
                handleReset
              }
              sx={{
                minWidth: "auto",

                px: 1.5,

                borderColor:
                  "#AFC5FF",

                color:
                  "#1264FF",

                fontWeight: 700,

                textTransform:
                  "none",

                whiteSpace:
                  "nowrap",

                flexShrink: 0,

                "&:hover": {
                  borderColor:
                    "#1264FF",

                  bgcolor:
                    "#F2F6FF",
                },
              }}
            >
              Reset
            </Button>
          </Stack>
        </Box>
      </Box>
    );
  }

  /**
   * =====================================================
   * FULL VERSION
   * =====================================================
   */

  return (
    <Box
      sx={{
        bgcolor: "#FFFFFF",

        border:
          "1px solid #E0E6EF",

        borderRadius: 4,

        px: {
          xs: 2.5,
          sm: 3,
          md: 4,
        },

        py: {
          xs: 3,
          md: 4,
        },

        boxShadow:
          "0 8px 30px rgba(23,43,77,0.04)",
      }}
    >
      {/* Header */}

      <Box mb={4}>
        <Typography
          variant="h3"
          sx={{
            fontSize: {
              xs: "2rem",
              md: "3rem",
            },

            lineHeight: 1.1,

            fontWeight: 800,

            color: "#172B4D",
          }}
        >
          Forecast Context
        </Typography>

        <Typography
          variant="body1"
          sx={{
            mt: 1,

            color: "#68758A",

            fontSize: {
              xs: "1rem",
              md: "1.25rem",
            },
          }}
        >
          Configure the forecast
          horizon, metric, entity
          and scenario.
        </Typography>
      </Box>

      {/* Selectors */}

      <Box
        sx={{
          display: "grid",

          gridTemplateColumns: {
            xs: "1fr",
            sm: "repeat(2, minmax(0, 1fr))",
            lg: "repeat(4, minmax(0, 1fr))",
          },

          gap: {
            xs: 2.5,
            md: 3,
          },
        }}
      >
        {/* Horizon */}

        <ContextField
          label="Horizon"
        >
          <Select
            value={horizon}
            onChange={
              handleHorizonChange
            }
            fullWidth
            IconComponent={
              KeyboardArrowDownRounded
            }
          >
            <MenuItem value="daily">
              Tactical (Daily - 90 Days)
            </MenuItem>

            <MenuItem value="monthly">
              Strategic (Monthly - 12 Months)
            </MenuItem>
          </Select>
        </ContextField>

        {/* Metric */}

        <ContextField
          label="Metric"
        >
          <Select
            value={metric}
            onChange={
              handleMetricChange
            }
            fullWidth
            IconComponent={
              KeyboardArrowDownRounded
            }
          >
            <MenuItem value="burn">
              Burn Predictions
            </MenuItem>

            <MenuItem value="supply">
              Supply Predictions
            </MenuItem>

            <MenuItem value="stockpile">
              Stockpile Predictions
            </MenuItem>
          </Select>
        </ContextField>

        {/* Entity */}

        <ContextField
          label="Forecast Entity"
        >
          <Select
            value={entityId}
            onChange={
              handleEntityChange
            }
            fullWidth
            IconComponent={
              KeyboardArrowDownRounded
            }
          >
            {renderEntityOptions()}
          </Select>
        </ContextField>

        {/* Scenario */}

        <ContextField
          label="Scenario"
        >
          <Select
            value={scenario}
            onChange={
              handleScenarioChange
            }
            fullWidth
            IconComponent={
              KeyboardArrowDownRounded
            }
          >
            <MenuItem value="actual">
              Baseline
            </MenuItem>

            <MenuItem value="hotdry">
              Hot &amp; Dry
            </MenuItem>

            <MenuItem value="hotwet">
              Hot &amp; Wet
            </MenuItem>

            <MenuItem value="colddry">
              Cold &amp; Dry
            </MenuItem>

            <MenuItem value="coldwet">
              Cold &amp; Wet
            </MenuItem>
          </Select>
        </ContextField>
      </Box>

      {/* Bottom controls */}

      <Stack
        direction={{
          xs: "column",
          sm: "row",
        }}
        justifyContent="space-between"
        alignItems={{
          xs: "flex-start",
          sm: "center",
        }}
        spacing={2}
        mt={4}
      >
        <Stack
          direction="row"
          alignItems="center"
          spacing={1}
        >
          <Typography
            variant="body1"
            color="#68758A"
          >
            Auto Refresh
          </Typography>

          <Switch
            checked={autoRefresh}
            onChange={(event) =>
              setAutoRefresh(
                event.target.checked
              )
            }
          />

          <Typography
            variant="body1"
            color="#68758A"
          >
            Updated{" "}
            {formattedUpdatedTime}
          </Typography>
        </Stack>

        <Button
          variant="outlined"
          startIcon={
            <RefreshRounded />
          }
          onClick={handleReset}
          sx={{
            minWidth: 160,

            height: 52,

            borderRadius: 2.5,

            borderWidth: 2,

            borderColor:
              "#8DB0FF",

            color:
              "#1264FF",

            fontSize: "1rem",

            fontWeight: 700,

            textTransform:
              "none",

            "&:hover": {
              borderWidth: 2,

              borderColor:
                "#1264FF",

              bgcolor:
                "#F2F6FF",
            },
          }}
        >
          Reset
        </Button>
      </Stack>
    </Box>
  );
};

/**
 * =====================================================
 * CONTEXT FIELD
 * =====================================================
 */

interface ContextFieldProps {
  label: string;
  children: React.ReactNode;
}

const ContextField = ({
  label,
  children,
}: ContextFieldProps) => {
  return (
    <FormControl fullWidth>
      <Typography
        variant="body1"
        fontWeight={700}
        color="#68758A"
        mb={1}
      >
        {label}
      </Typography>

      {React.isValidElement(children)
        ? React.cloneElement(
            children as React.ReactElement<any>,
            {
              sx: {
                height: 58,

                borderRadius: 2.5,

                bgcolor: "#FFFFFF",

                "& .MuiOutlinedInput-notchedOutline":
                  {
                    borderColor:
                      "#CFD7E4",

                    borderWidth: 1.5,
                  },

                "&:hover .MuiOutlinedInput-notchedOutline":
                  {
                    borderColor:
                      "#8DB0FF",
                  },

                "&.Mui-focused .MuiOutlinedInput-notchedOutline":
                  {
                    borderColor:
                      "#1264FF",

                    borderWidth: 2,
                  },

                "& .MuiSelect-select":
                  {
                    display:
                      "flex",

                    alignItems:
                      "center",

                    fontSize:
                      "1.05rem",

                    fontWeight: 600,

                    color:
                      "#172B4D",
                  },
              },
            }
          )
        : children}
    </FormControl>
  );
};

/**
 * =====================================================
 * COMPACT SELECT
 * =====================================================
 */

interface CompactSelectProps {
  value: string;

  onChange: (
    event: SelectChangeEvent<string>
  ) => void;

  children: React.ReactNode;

  width:
    | number
    | {
        xs?: number;
        md?: number;
      };
}

const CompactSelect = ({
  value,
  onChange,
  children,
  width,
}: CompactSelectProps) => {
  return (
    <Select
      size="small"
      value={value}
      onChange={onChange}
      IconComponent={
        KeyboardArrowDownRounded
      }
      sx={{
        width,

        flexShrink: 0,

        height: 40,

        borderRadius: 2,

        bgcolor: "#FFFFFF",

        "& .MuiOutlinedInput-notchedOutline":
          {
            borderColor:
              "#CBD5E3",
          },

        "&:hover .MuiOutlinedInput-notchedOutline":
          {
            borderColor:
              "#8DB0FF",
          },

        "&.Mui-focused .MuiOutlinedInput-notchedOutline":
          {
            borderColor:
              "#1264FF",

            borderWidth: 1.5,
          },

        "& .MuiSelect-select":
          {
            py: 0.75,

            px: 1.5,

            fontSize:
              "0.85rem",

            fontWeight: 700,

            color:
              "#172B4D",

            whiteSpace:
              "nowrap",

            overflow:
              "hidden",

            textOverflow:
              "ellipsis",
          },
      }}
    >
      {children}
    </Select>
  );
};

export default ForecastContextBar;
